60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * Maximum number of owners allowed to be registered in a single city. A new owner
67	     * whose city already holds this many owners is rejected as a conflict.
68	     */
69	    private static final long MAX_OWNERS_PER_CITY = 50;
70	
71	    /**
72	     * Maximum number of owners allowed to be registered in a single day. Once this many
73	     * owners already carry today's registration date, a further create is rejected as
74	     * too many requests.
75	     */
76	    private static final long MAX_OWNERS_PER_DAY = 100;
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final TelephoneNormalizer telephoneNormalizer;
87	
88	    private final EmailNormalizer emailNormalizer;
89	
90	    private final AddressNormalizer addressNormalizer;
91	
92	    private final PostcodeValidator postcodeValidator;
93	
94	    private final OwnerAuditLogger ownerAuditLogger;
95	
96	    private final OwnerCreationIdempotencyStore idempotencyStore;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper,
102	                                 TelephoneNormalizer telephoneNormalizer,
103	                                 EmailNormalizer emailNormalizer,
104	                                 AddressNormalizer addressNormalizer,
105	                                 PostcodeValidator postcodeValidator,
106	                                 OwnerAuditLogger ownerAuditLogger,
107	                                 OwnerCreationIdempotencyStore idempotencyStore) {
108	        this.clinicService = clinicService;
109	        this.ownerMapper = ownerMapper;
110	        this.petMapper = petMapper;
111	        this.visitMapper = visitMapper;
112	        this.telephoneNormalizer = telephoneNormalizer;
113	        this.emailNormalizer = emailNormalizer;
114	        this.addressNormalizer = addressNormalizer;
115	        this.postcodeValidator = postcodeValidator;
116	        this.ownerAuditLogger = ownerAuditLogger;
117	        this.idempotencyStore = idempotencyStore;
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
123	        Collection<Owner> owners;
124	        if (lastName != null) {
125	            owners = this.clinicService.findOwnerByLastName(lastName);
126	        } else {
127	            owners = this.clinicService.findAllOwners();
128	        }
129	        if (owners.isEmpty()) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
143	    }
144	
145	    /**
146	     * Normalize the owner's supplied address into its canonical stored form, preferring
147	     * the structured fields over the flat address. When a non-blank {@code addressLine1}
148	     * is supplied it wins: both structured lines are normalized and the stored
149	     * {@code address} becomes their composed value; otherwise the flat {@code address} is
150	     * normalized and used. The owner is left with a normalized structured/flat address.
151	     *
152	     * @param owner the owner whose address fields are normalized in place
153	     * @return {@code true} if the owner supplies an address in either form, {@code false}
154	     * when neither a structured nor a flat address was given
155	     */
156	    private boolean normalizeAddress(Owner owner) {
157	        String addressLine1 = addressNormalizer.normalize(owner.getAddressLine1());
158	        String addressLine2 = addressNormalizer.normalize(owner.getAddressLine2());
159	        String flatAddress = addressNormalizer.normalize(owner.getAddress());
160	        owner.setAddressLine2(addressNormalizer.isBlank(addressLine2) ? null : addressLine2);
161	        if (!addressNormalizer.isBlank(addressLine1)) {
162	            owner.setAddressLine1(addressLine1);
163	            owner.setAddress(addressNormalizer.compose(addressLine1, addressLine2));
164	            return true;
165	        }
166	        owner.setAddressLine1(null);
167	        if (!addressNormalizer.isBlank(flatAddress)) {
168	            owner.setAddress(flatAddress);
169	            return true;
170	        }
171	        return false;
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
177	        Owner replay = replayIdempotentCreate(idempotencyKey);
178	        if (replay != null) {
179	            return new ResponseEntity<>(ownerMapper.toOwnerDto(replay), HttpStatus.OK);
180	        }
181	        HttpHeaders headers = new HttpHeaders();
182	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
183	        if (!normalizeAddress(owner)) {
184	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
185	        }
186	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
187	        if (e164Telephone.isEmpty()) {
188	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
189	        }
190	        String telephone = e164Telephone.get();
191	        String email = emailNormalizer.normalize(owner.getEmail());
192	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
193	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
194	        }
195	        if (owner.getPostcode() != null && !postcodeValidator.isValid(owner.getPostcode(), owner.getCity())) {
196	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
197	        }
198	        LocalDate suppliedRegistrationDate = owner.getRegistrationDate();
199	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
200	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
201	        }
202	        LocalDate registrationDate = BusinessDay.rollForward(
203	            suppliedRegistrationDate == null ? LocalDate.now() : suppliedRegistrationDate);
204	        owner.setRegistrationDate(registrationDate);
205	        if (clinicService.countOwnersByRegistrationDate(registrationDate) >= MAX_OWNERS_PER_DAY) {
206	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
207	        }
208	        owner.setTelephone(telephone);
209	        owner.setEmail(email);
210	        if (clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        // The household is keyed on (last name, postcode): a second owner sharing both is a
214	        // household duplicate and is rejected, unless it declares 'sharesHousehold', which
215	        // bypasses this block and creates it as a (non-suspected) declared household member.
216	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
217	        if (!sharesHousehold && clinicService.isHouseholdOccupied(owner)) {
218	            return new ResponseEntity<>(HttpStatus.CONFLICT);
219	        }
220	        owner.setDeclaredHouseholdMember(sharesHousehold);
221	        this.clinicService.saveOwner(owner);
222	        this.ownerAuditLogger.logCreated(owner);
223	        if (idempotencyKey != null) {
224	            this.idempotencyStore.remember(idempotencyKey, owner.getId());
225	        }
226	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
227	        headers.setLocation(UriComponentsBuilder.newInstance()
228	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
229	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
230	    }
231	
232	    /**
233	     * Look up the owner already created under the given {@code Idempotency-Key}, if any.
234	     * A repeated create carrying a key that has already produced an owner replays that
235	     * original owner instead of creating a duplicate.
236	     *
237	     * @param idempotencyKey the client-supplied idempotency key, or {@code null} when the
238	     *                       request carries no {@code Idempotency-Key} header
239	     * @return the originally created owner to replay, or {@code null} when the key is
240	     * absent, unseen, or its owner no longer exists
241	     */
242	    private Owner replayIdempotentCreate(String idempotencyKey) {
243	        if (idempotencyKey == null) {
244	            return null;
245	        }
246	        return idempotencyStore.findOwnerId(idempotencyKey)
247	            .map(clinicService::findOwnerById)
248	            .orElse(null);
249	    }
250	
251	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
252	    @Override
253	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
254	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
255	        if (currentOwner == null) {
256	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
257	        }
258	        Optional<String> e164Telephone = telephoneNormalizer.toE164(ownerFieldsDto.getTelephone());
259	        if (e164Telephone.isEmpty()) {
260	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
261	        }
262	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
263	        if (email != null && (!emailNormalizer.isValid(email) || emailNormalizer.isDisposable(email))) {
264	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
265	        }
266	        String postcode = ownerFieldsDto.getPostcode();
267	        if (postcode != null && !postcodeValidator.isValid(postcode, ownerFieldsDto.getCity())) {
268	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
269	        }
270	        currentOwner.setAddress(ownerFieldsDto.getAddress());
271	        currentOwner.setCity(ownerFieldsDto.getCity());
272	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
273	        currentOwner.setLastName(ownerFieldsDto.getLastName());
274	        currentOwner.setTelephone(e164Telephone.get());
275	        currentOwner.setEmail(email);
276	        currentOwner.setPostcode(postcode);
277	        this.clinicService.saveOwner(currentOwner);
278	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Transactional
283	    @Override
284	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
285	        Owner owner = this.clinicService.findOwnerById(ownerId);
286	        if (owner == null) {
287	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
288	        }
289	        this.clinicService.deleteOwner(owner);
290	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
291	    }
292	
293	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
294	    @Override
295	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
296	        Owner owner = this.clinicService.findOwnerById(ownerId);
297	        if (owner == null) {
298	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
299	        }
300	        HttpHeaders headers = new HttpHeaders();
301	        Pet pet = petMapper.toPet(petFieldsDto);
302	        owner.setId(ownerId);
303	        pet.setOwner(owner);
304	        pet.getType().setName(null);
305	        this.clinicService.savePet(pet);
306	        PetDto petDto = petMapper.toPetDto(pet);
307	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
308	            .buildAndExpand(pet.getId()).toUri());
309	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
310	    }
311	
312	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
313	    @Override
314	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
315	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
316	        if (currentOwner != null) {
317	            Pet currentPet = this.clinicService.findPetById(petId);
318	            if (currentPet != null) {
319	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
320	                currentPet.setName(petFieldsDto.getName());
321	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
322	                this.clinicService.savePet(currentPet);
323	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
324	            }
325	        }
326	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
327	    }
328	
329	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
330	    @Override
331	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
332	        HttpHeaders headers = new HttpHeaders();
333	        Visit visit = visitMapper.toVisit(visitFieldsDto);
334	        Pet pet = new Pet();
335	        pet.setId(petId);
336	        visit.setPet(pet);
337	        this.clinicService.saveVisit(visit);
338	        VisitDto visitDto = visitMapper.toVisitDto(visit);
339	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
340	            .buildAndExpand(visit.getId()).toUri());
341	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
342	    }
343	
344	
345	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
346	    @Override
347	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
348	        Owner owner = this.clinicService.findOwnerById(ownerId);
349	        if (owner != null) {
350	            Pet pet = owner.getPet(petId);
351	            if (pet != null) {
352	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
353	            }
354	        }
355	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
356	    }
357	}
