26	 * so a create that repeats with an already-seen key can return the originally created
27	 * owner instead of creating a duplicate.
28	 */
29	@Component
30	public class OwnerCreationIdempotencyStore {
31	
32	    private final Map<String, Integer> ownerIdsByKey = new ConcurrentHashMap<>();
33	
34	    /**
35	     * The id of the owner previously created under {@code key}, or empty if the key has
36	     * not been seen.
37	     */
38	    public Optional<Integer> findOwnerId(String key) {
39	        return Optional.ofNullable(ownerIdsByKey.get(key));
40	    }
41	
42	    /**
43	     * Remember that the owner with {@code ownerId} was the one created under {@code key}.
44	     * The first owner recorded for a key wins, so concurrent repeats stay consistent.
45	     */
46	    public void remember(String key, Integer ownerId) {
47	        ownerIdsByKey.putIfAbsent(key, ownerId);
48	    }
49	}
