250	    @Override
251	    @Transactional
252	    public void saveOwner(Owner owner) throws DataAccessException {
253	        if (owner.isNew()) {
254	            if (owner.getCustomerCode() == null) {
255	                owner.setCustomerCode(customerCodeGenerator.generateUnique(
256	                    RegionResolver.regionFor(owner.getPostcode(), owner.getCity()),
257	                    owner.getTelephone(), owner.getLastName(),
258	                    ownerRepository::existsByCustomerCode));
259	            }
260	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
261	            owner.setBulkSignupWarning(
262	                ownerRepository.countByRegistrationDate(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
263	            owner.setHouseholdId(householdIdFor(owner));
264	            owner.setHouseholdSize(householdSizeIncluding(owner));
265	            Optional<Owner> possibleDuplicate = findPossibleDuplicate(owner);
266	            owner.setPossibleDuplicate(possibleDuplicate.isPresent());
267	            owner.setPossibleDuplicateOf(possibleDuplicate.map(Owner::getId).orElse(null));
268	        }
269	        ownerRepository.save(owner);
270	
271	    }
