273	    /**
274	     * The deterministic, shared household id this owner maps to, derived from its last
275	     * name and postcode so that owners sharing both belong to the same household.
276	     */
277	    private String householdIdFor(Owner owner) {
278	        return householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
279	    }
280	
281	    /**
282	     * Size of the household this new owner will belong to once persisted: the owners
283	     * already sharing its household id, plus the owner itself. An owner with no shared
284	     * household id stands alone, so its household size is one.
285	     */
286	    private int householdSizeIncluding(Owner owner) {
287	        if (owner.getHouseholdId() == null) {
288	            return 1;
289	        }
290	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
291	    }
292	
293	    /**
294	     * Count the existing owners that already share the given first and last name,
295	     * compared case-insensitively. Used to stamp a new owner's namesake count at
296	     * registration, before it is itself persisted.
297	     */
298	    private int countNamesakes(String firstName, String lastName) {
299	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
300	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
301	            .count();
302	    }
303	
304	    /**
305	     * Find the existing owner, if any, that this new owner is a possible (soft) duplicate
306	     * of: one that occupies the same household (the same computed household id) but carries
307	     * a different telephone, so it is not a hard duplicate. When several match, the earliest
308	     * (lowest id) is chosen. An owner that belongs to no household (no household id), or one
309	     * that deliberately declared it shares a household, is never a suspected duplicate.
310	     */
311	    private Optional<Owner> findPossibleDuplicate(Owner owner) {
312	        String householdId = owner.getHouseholdId();
313	        if (householdId == null || owner.isDeclaredHouseholdMember()) {
314	            return Optional.empty();
315	        }
316	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
317	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
318	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
319	            .min(Comparator.comparing(Owner::getId));
320	    }
