18	
19	import java.util.Optional;
20	import java.util.regex.Pattern;
21	
22	import org.springframework.samples.petclinic.model.CountryCallingCode;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Normalizes and validates an owner's telephone number into E.164 form.
27	 *
28	 * <p>A leading {@code '+'} and country code are kept when present; otherwise the
29	 * default country code {@link #DEFAULT_COUNTRY_CODE} is assumed and a single
30	 * leading {@code '0'} is dropped from the national digits. Spaces, dashes and
31	 * brackets are stripped. The result is only accepted when it carries between
32	 * {@link #MIN_DIGITS} and {@link #MAX_DIGITS} digits after the {@code '+'} and,
33	 * for a recognised country code, exactly as many national digits as that
34	 * country requires (see {@link CountryCallingCode}).
35	 */
36	@Component
37	public class TelephoneNormalizer {
38	
39	    /** Country code assumed when the raw number has no explicit {@code '+'} prefix. */
40	    public static final String DEFAULT_COUNTRY_CODE = "61";
41	
42	    /** The fewest digits a valid E.164 number may have after the {@code '+'}. */
43	    public static final int MIN_DIGITS = 8;
44	
45	    /** The most digits a valid E.164 number may have after the {@code '+'}. */
46	    public static final int MAX_DIGITS = 15;
47	
48	    /** Separators that carry no numeric meaning and are stripped before parsing. */
49	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
50	
51	    private static final Pattern DIGITS = Pattern.compile("\\d+");
52	
53	    /**
54	     * Convert a raw telephone value into its E.164 representation.
55	     *
56	     * @param telephone the raw telephone value (may be {@code null})
57	     * @return the E.164 number (e.g. {@code "+61412345678"}), or
58	     *         {@link Optional#empty()} if it cannot form a valid E.164 number
59	     */
60	    public Optional<String> toE164(String telephone) {
61	        if (telephone == null) {
62	            return Optional.empty();
63	        }
64	        String trimmed = telephone.trim();
65	        boolean explicitCountryCode = trimmed.startsWith("+");
66	        String body = explicitCountryCode ? trimmed.substring(1) : trimmed;
67	        String digits = SEPARATORS.matcher(body).replaceAll("");
68	        if (!DIGITS.matcher(digits).matches()) {
69	            return Optional.empty();
70	        }
71	        if (!explicitCountryCode) {
72	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
73	            digits = DEFAULT_COUNTRY_CODE + national;
74	        }
75	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
76	            return Optional.empty();
77	        }
78	        if (!hasValidNationalLength(digits)) {
79	            return Optional.empty();
80	        }
81	        return Optional.of("+" + digits);
82	    }
83	
84	    /**
85	     * Check that the national number has the exact length its country code
86	     * requires. Numbers whose country code is not recognised are accepted here;
87	     * only the generic length bounds constrain them.
88	     *
89	     * @param digits the E.164 digits (country code followed by the national number)
90	     * @return {@code true} if the national-number length matches the country code
91	     */
92	    private boolean hasValidNationalLength(String digits) {
93	        return CountryCallingCode.of(digits)
94	            .map(code -> digits.length() - code.length() == CountryCallingCode.nationalDigits(code).orElseThrow())
95	            .orElse(true);
96	    }
97	}
