18	
19	import java.util.regex.Pattern;
20	
21	import org.springframework.samples.petclinic.model.CityRegionTable;
22	import org.springframework.samples.petclinic.model.RegionPostcodeTable;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Validates an owner's postcode. A postcode is optional, but when supplied it must be
27	 * exactly four digits and fall within the range valid for the region derived from the
28	 * owner's city (see {@link CityRegionTable} and {@link RegionPostcodeTable}). A city
29	 * whose region has no known range accepts any 4-digit postcode.
30	 */
31	@Component
32	public class PostcodeValidator {
33	
34	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
35	
36	    /**
37	     * @param postcode a supplied (non-{@code null}) postcode value
38	     * @param city     the owner's city, used to derive the applicable region
39	     * @return {@code true} if the postcode is four digits and valid for the city's region
40	     */
41	    public boolean isValid(String postcode, String city) {
42	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
43	            return false;
44	        }
45	        return RegionPostcodeTable.accepts(CityRegionTable.regionFor(city), Integer.parseInt(postcode));
46	    }
47	}
