16	package org.springframework.samples.petclinic.model;
17	
18	import java.time.LocalDate;
19	
20	/**
21	 * Business-day rules for registration dates.
22	 *
23	 * <p>A registration date must fall on a business day: any Saturday, Sunday, or
24	 * {@link PublicHolidays public holiday} rolls forward to the next date that is none of
25	 * those, while an ordinary weekday is left unchanged. This is the single source of truth
26	 * for that adjustment, so callers never repeat it.
27	 */
28	public final class BusinessDay {
29	
30	    private BusinessDay() {
31	    }
32	
33	    /**
34	     * Roll a date forward onto a business day.
35	     *
36	     * @param date the date to adjust
37	     * @return the earliest date on or after {@code date} that is neither a weekend nor a
38	     *         public holiday
39	     */
40	    public static LocalDate rollForward(LocalDate date) {
41	        LocalDate adjusted = date;
42	        while (!isBusinessDay(adjusted)) {
43	            adjusted = adjusted.plusDays(1);
44	        }
45	        return adjusted;
46	    }
47	
48	    private static boolean isBusinessDay(LocalDate date) {
49	        return switch (date.getDayOfWeek()) {
50	            case SATURDAY, SUNDAY -> false;
51	            default -> !PublicHolidays.contains(date);
52	        };
53	    }
54	}
