17	
18	import java.time.LocalDate;
19	import java.util.Collection;
20	import java.util.List;
21	
22	import jakarta.persistence.EntityManager;
23	import jakarta.persistence.PersistenceContext;
24	import jakarta.persistence.Query;
25	
26	import org.jspecify.annotations.NonNull;
27	import org.springframework.context.annotation.Profile;
28	import org.springframework.dao.DataAccessException;
29	import org.springframework.data.domain.Page;
30	import org.springframework.data.domain.PageImpl;
31	import org.springframework.data.domain.Pageable;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.repository.OwnerRepository;
34	import org.springframework.stereotype.Repository;
35	
36	/**
37	 * JPA implementation of the {@link OwnerRepository} interface.
38	 *
39	 * @author Mike Keith
40	 * @author Rod Johnson
41	 * @author Sam Brannen
42	 * @author Michael Isvy
43	 * @author Vitaliy Fedoriv
44	 */
45	@Repository
46	@Profile("jpa")
47	public class JpaOwnerRepositoryImpl implements OwnerRepository {
48	
49	    @PersistenceContext
50	    private EntityManager em;
51	
52	
53	    /**
54	     * Important: in the current version of this method, we load Owners with all their Pets and Visits while
55	     * we do not need Visits at all and we only need one property from the Pet objects (the 'name' property).
56	     * There are some ways to improve it such as:
57	     * - creating a Ligtweight class (example here: https://community.jboss.org/wiki/LightweightClass)
58	     * - Turning on lazy-loading and using open session in view pattern
59	     */
60	    @SuppressWarnings("unchecked")
61	    public Collection<Owner> findByLastName(String lastName) {
62	        // using 'join fetch' because a single query should load both owners and pets
63	        // using 'left join fetch' because it might happen that an owner does not have pets yet
64	        Query query = this.em.createQuery("SELECT DISTINCT owner FROM Owner owner left join fetch owner.pets WHERE owner.lastName LIKE :lastName");
65	        query.setParameter("lastName", lastName + "%");
66	        return query.getResultList();
67	    }
68	
69	    @Override
70	    @SuppressWarnings("unchecked")
71	    public Page<Owner> findByLastName(String lastName, Pageable pageable) throws DataAccessException {
72	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE owner.lastName LIKE :lastName ORDER BY owner.id");
73	        query.setParameter("lastName", lastName + "%");
74	        query.setFirstResult((int) pageable.getOffset());
75	        query.setMaxResults(pageable.getPageSize());
76	        List<Owner> owners = query.getResultList();
77	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner WHERE owner.lastName LIKE :lastName");
78	        countQuery.setParameter("lastName", lastName + "%");
79	        long total = (long) countQuery.getSingleResult();
80	        return new PageImpl<>(owners, pageable, total);
81	    }
82	
83	    @Override
84	    public Owner findById(int id) {
85	        // using 'join fetch' because a single query should load both owners and pets
86	        // using 'left join fetch' because it might happen that an owner does not have pets yet
87	        Query query = this.em.createQuery("SELECT owner FROM Owner owner left join fetch owner.pets WHERE owner.id =:id");
88	        query.setParameter("id", id);
89	        return (Owner) query.getSingleResult();
90	    }
91	
92	
93	    @Override
94	    @SuppressWarnings("unchecked")
95	    public Collection<Owner> findByLastNameIgnoreCase(String lastName) throws DataAccessException {
96	        Query query = this.em.createQuery("SELECT owner FROM Owner owner WHERE LOWER(owner.lastName) = LOWER(:lastName) AND owner.deleted = false");
97	        query.setParameter("lastName", lastName);
98	        return query.getResultList();
99	    }
100	
101	    @Override
102	    public void save(Owner owner) {
103	        if (owner.getId() == null) {
104	            this.em.persist(owner);
105	        } else {
106	            this.em.merge(owner);
107	        }
108	
109	    }
110	
111		@SuppressWarnings("unchecked")
112		@Override
113		public Collection<Owner> findAll() throws DataAccessException {
114			Query query = this.em.createQuery("SELECT owner FROM Owner owner");
115	        return query.getResultList();
116		}
117	
118	    @SuppressWarnings("unchecked")
119	    @Override
120	    public Page<Owner> findAll(@NonNull Pageable pageable) throws DataAccessException {
121	        Query query = this.em.createQuery("SELECT owner FROM Owner owner ORDER BY owner.id");
122	        query.setFirstResult((int) pageable.getOffset());
123	        query.setMaxResults(pageable.getPageSize());
124	        List<Owner> owners = query.getResultList();
125	        Query countQuery = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
126	        long total = (long) countQuery.getSingleResult();
127	        return new PageImpl<>(owners, pageable, total);
128	    }
129	
130		@Override
131		public void delete(Owner owner) throws DataAccessException {
132			this.em.remove(this.em.contains(owner) ? owner : this.em.merge(owner));
133		}
134	
135	    @Override
136	    public long count() throws DataAccessException {
137	        Query query = this.em.createQuery("SELECT COUNT(owner) FROM Owner owner");
138	        return (long) query.getSingleResult();
139	    }
140	
141	    @Override
142	    public long countByCity(String city) throws DataAccessException {
143	        Query query = this.em.createQuery(
144	            "SELECT COUNT(owner) FROM Owner owner WHERE LOWER(owner.city) = LOWER(:city)");
145	        query.setParameter("city", city);
146	        return (long) query.getSingleResult();
147	    }
148	
149	    @Override
150	    public long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
151	        Query query = this.em.createQuery(
152	            "SELECT COUNT(owner) FROM Owner owner WHERE owner.registrationDate = :registrationDate");
153	        query.setParameter("registrationDate", registrationDate);
154	        return (long) query.getSingleResult();
155	    }
156	
157	    @Override
158	    public long countByHouseholdId(String householdId) throws DataAccessException {
159	        Query query = this.em.createQuery(
160	            "SELECT COUNT(owner) FROM Owner owner WHERE owner.householdId = :householdId AND owner.deleted = false");
161	        query.setParameter("householdId", householdId);
162	        return (long) query.getSingleResult();
163	    }
164	
165	    @Override
166	    public boolean existsByCustomerCode(String customerCode) throws DataAccessException {
167	        Query query = this.em.createQuery(
168	            "SELECT COUNT(owner) FROM Owner owner WHERE owner.customerCode = :customerCode AND owner.deleted = false");
169	        query.setParameter("customerCode", customerCode);
170	        return (long) query.getSingleResult() > 0;
171	    }
172	
173	}
